-- ============================================================================
-- FC8: Metering, Control Valves & Storage joins the catalog, a Facilities
-- course at path_order 46.
--
-- Catalog row (module 'facilities'; path_order 46 in the Facilities block that
-- runs from FC1 separation at 39; prereq_slug NULL, the carried-over answer "no
-- hard prerequisite inside a module") plus the three capstones and their
-- eighteen graded fields, generated by tools/course-waves/metering/gen_course.py
-- from fields.json, precision.json and the capstone constants in
-- fc8_capstone.mjs. Deep seeds are three separate migrations; the go-live is a
-- fifth and is HELD until a NextGen production upload carries the route
-- /dashboard/apps/metering, because the 78 lessons, the teaching lab
-- (meteringLab.js) and its four explorer panels ship in the zip and not in this
-- database.
--
-- THE ONE SENTENCE THE COURSE IS. A meter run, a control valve and a tank are
-- the three places on a facility where a number that looks like a measurement
-- is a design judgement with a standard behind it, and where the behaviour that
-- matters lives at a boundary the ordinary equation walks straight past.
--
-- THE ENGINES. engines/facilities/metering.js, controlValve.js and
-- storageTank.js, vendored from engines main 9874d583 with the FC8-0 repair,
-- byte-identical and proved three independent ways (tools/course-waves/metering
-- vendor/closure.json).
--
-- NOTHING GRADED RESTS ON A HELD, UNCITED OR WITHHELD ITEM. The three engines
-- name fifteen, and two are outright refusals: the straight run for two elbows
-- in different planes, and the relation that turns a fire duty into a required
-- vent capacity. Neither is graded anywhere. Where a capstone needs a value an
-- engine calls its own stated data, the capstone STATES it: UTONANA states its
-- certified FL, SAGHARA its allowable stresses, its minimum plate, its thermal
-- rate, its latitude factor, its low-volatility factor and its proportional
-- limit, and KRAKAMA every term of its uncertainty budget. SAGHARA's annual
-- loss is stated off a measured record, so AP-42 and its turnover factor are
-- not called. fc8_capstone.mjs measures each clearance rather than asserting
-- it, and the go-live asserts all eighteen again by closed form.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, at each
-- field's own shipped tolerance: 0 collisions, and 0 pairwise.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('metering', 'Metering, Control Valves & Storage', 'facilities', 46, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'metering', 'beginner', 'associate',
  'KRAKAMA, a gas export meter run read as a measurement and as a budget',
  'What the meter run measures, and how well',
  'KRAKAMA, the gas export meter run on a flow station. A flange-tapped orifice plate with a bore of 3.8747 inches sits in a line of 7.981 inches inside diameter. The differential transmitter is spanned at 425 inches of water with an accuracy of 0.072 percent of span, and at design it reads 87.43 inches of water. The gas crosses the plate at a static pressure of 614.7 psia with a flowing density of 3.1642 lb per ft3, a viscosity of 0.0134 cP and a specific heat ratio of 1.29. The uncertainty budget states every term rather than taking a default: 0.47 percent on the discharge coefficient, 0.18 percent on the expansibility, 0.043 percent on the orifice bore, 0.11 percent on the pipe bore and 0.28 percent on the density, with the differential term taken from the transmitter at the design reading. On the liquid side of the same station a turbine meter counted 4187233 pulses over the proving period against a K factor of 912.47 pulses per bbl, and the proving run returned a meter factor of 1.0034. Report six values: the beta ratio of the orifice run, the design differential in psi, the transmitter uncertainty as a percent of the design reading, the flow turndown at the design reading, the total uncertainty of the mass flow as a percent, and the gross volume the turbine meter recorded. The volume in bbl, to four decimals. The ratios, the differential and the percentages to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','krakama_beta_ratio', 'label','The beta ratio of the orifice run', 'unit','ratio', 'expected',0.48549054003257736, 'tol',5e-07),
    jsonb_build_object('key','krakama_differential_psi', 'label','The design differential, in psi', 'unit','psi', 'expected',3.1586098390000004, 'tol',5e-07),
    jsonb_build_object('key','krakama_transmitter_uncertainty_pct', 'label','The transmitter uncertainty as a percent of the design reading', 'unit','percent of reading', 'expected',0.349994281139197, 'tol',5e-07),
    jsonb_build_object('key','krakama_flow_turndown_ratio', 'label','The flow turndown at the design reading', 'unit','ratio', 'expected',2.204774746428498, 'tol',5e-07),
    jsonb_build_object('key','krakama_total_uncertainty_pct', 'label','The total uncertainty of the mass flow', 'unit','percent of flow', 'expected',0.5585545354757169, 'tol',5e-07),
    jsonb_build_object('key','krakama_turbine_gross_bbl', 'label','The gross volume the turbine meter recorded', 'unit','bbl', 'expected',4604.50161890254, 'tol',5e-05)
  )
),
(
  'metering', 'intermediate', 'professional',
  'UTONANA, a control valve on a hot condensate transfer, sized either side of its choking boundary',
  'The choking boundary and what sits either side of it',
  'UTONANA, the control valve on a hot condensate transfer. It passes 742.6 US gallons a minute of a liquid with a specific gravity of 0.7134, from an inlet at 428.3 psia to an outlet at 72.4 psia. The liquid''s true vapour pressure at its flowing temperature is 41.62 psia and its critical pressure is 566.8 psia. The trim''s certified liquid pressure recovery factor FL is 0.93, stated by the vendor and used in place of any table value, there is no piping geometry correction, and the service is fully turbulent. The system around the valve takes a total pressure drop of 452.8 psi at design flow, and the valve''s own share of it is the drop from its inlet to its outlet. The trim is equal percentage with a rated coefficient of 88 and a rangeability of 42.5, and the coefficients the three duties require are 11.85 at the minimum, 34.62 at the normal and 47.3 at the maximum. Report six values: the liquid critical pressure ratio factor FF, the allowable pressure drop in psi, the liquid valve coefficient the service needs, the cavitation index on the drop the valve uses, the valve authority at design flow, and the travel at the normal duty in percent open. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','utonana_ff_critical_ratio', 'label','The liquid critical pressure ratio factor FF', 'unit','ratio', 'expected',0.884125795896952, 'tol',5e-07),
    jsonb_build_object('key','utonana_allowable_drop_psi', 'label','The allowable pressure drop the valve can use', 'unit','psi', 'expected',338.6106717157376, 'tol',5e-07),
    jsonb_build_object('key','utonana_liquid_cv', 'label','The liquid valve coefficient the service needs', 'unit','Cv', 'expected',34.0856183317242, 'tol',5e-07),
    jsonb_build_object('key','utonana_cavitation_sigma', 'label','The cavitation index on the drop the valve uses', 'unit','ratio', 'expected',1.1419604646265147, 'tol',5e-07),
    jsonb_build_object('key','utonana_valve_authority', 'label','The valve authority at design flow', 'unit','ratio', 'expected',0.7859982332155476, 'tol',5e-07),
    jsonb_build_object('key','utonana_normal_travel_pct', 'label','The travel at the normal duty', 'unit','percent open', 'expected',75.119235881917, 'tol',5e-07)
  )
),
(
  'metering', 'advanced', 'expert',
  'SAGHARA, a fixed-roof tank read on its shell, its venting and its losses',
  'The tank farm, read on the engine''s own verdicts',
  'SAGHARA, a fixed-roof tank on a crude terminal. The shell is 78.4 ft in diameter and 44 ft high, built in 8 ft courses, with a design liquid level of 42.6 ft. It is designed by the one-foot method at a design allowable stress of 25300 psi and a hydrostatic test allowable stress of 27000 psi, with a corrosion allowance of 0.0625 inch added to the design condition only, and the minimum plate thickness in force is stated at 0.25 inch. The product has a specific gravity of 0.8312. The tank is uninsulated and holds a low volatility product, and its venting is stated rather than defaulted: a thermal rate of 1.12 scfh of air per barrel of nominal capacity, a latitude factor of 1.08, a low-volatility outbreathing factor of 0.58, and a capacity of 41500 bbl above which proportionality is no longer claimed. It is filled at 4820 bbl an hour and drawn at 1150 bbl an hour. The terminal''s own measured inventory record puts the uncontrolled evaporative loss at 214860 lb a year, and the vapour recovery unit proposed for it is quoted at 93.4 percent. Report six values: the required thickness of the bottom course in inches, the product specific gravity below which the hydrostatic test would take the bottom course instead, the total inbreathing in scfh at the stated rates, the draw rate in bbl an hour above which vacuum would govern the venting, the working capacity in bbl to the design liquid level, and the annual loss in lb that the recovery unit saves. The thickness and the gravity to six decimals. The inbreathing, the draw rate, the capacity and the saving to four decimals.',
  jsonb_build_array(
    jsonb_build_object('key','saghara_bottom_course_required_in', 'label','The required thickness of the bottom course', 'unit','in', 'expected',0.3410914313359685, 'tol',5e-07),
    jsonb_build_object('key','saghara_sg_at_which_test_governs', 'label','The product gravity below which the water test takes the bottom course', 'unit','specific gravity', 'expected',0.7505632472622514, 'tol',5e-07),
    jsonb_build_object('key','saghara_inbreathing_scfh', 'label','The total inbreathing at the stated rates', 'unit','scfh', 'expected',52218.131495532485, 'tol',5e-05),
    jsonb_build_object('key','saghara_vacuum_governing_draw_bblhr', 'label','The draw rate above which vacuum governs the venting', 'unit','bbl/hr', 'expected',1396.812501113412, 'tol',5e-05),
    jsonb_build_object('key','saghara_working_capacity_bbl', 'label','The working capacity to the design liquid level', 'unit','bbl', 'expected',36628.07322123172, 'tol',5e-05),
    jsonb_build_object('key','saghara_recovery_saved_lb_yr', 'label','The annual loss the recovery unit saves', 'unit','lb/yr', 'expected',200679.24000000002, 'tol',5e-05)
  )
)
on conflict (app_slug, tier) do nothing;
